import{_ as l,a0 as p,w as u,s as r,ao as a,I as e,x as t,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ubuntu 中的 root 用户：你應該知道的重要事情 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 中的 root 用户：你應該知道的重要事情 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 中的 root 用户：你應該知道的重要事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 中的 root 用户：你應該知道的重要事情 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200115 Root User in Ubuntu- Important Things You Should Know","title":"Ubuntu 中的 root 用户：你應該知道的重要事情","tag":"202001","desc":""},"relativePath":"202001/20200115 Root User in Ubuntu- Important Things You Should Know.md","filePath":"[post].md"}'),d={name:"202001/20200115 Root User in Ubuntu- Important Things You Should Know.md"};function b(h,s,g,k,f,c){const o=p("Link");return u(),r("div",null,[s[30]||(s[30]=a('<h1 id="ubuntu-中的-root-用户-你應該知道的重要事情" tabindex="-1">Ubuntu 中的 root 用户：你應該知道的重要事情 <a class="header-anchor" href="#ubuntu-中的-root-用户-你應該知道的重要事情" aria-label="Permalink to “Ubuntu 中的 root 用户：你應該知道的重要事情”">​</a></h1><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/01/root_user_ubuntu.png?ssl=1" alt=""></p><p>當你剛開始使用 Linux 時，你將發現與 Windows 的很多不同。其中一個“不同的東西”是 root 用户的概念。</p><p>在這個初學者系列中，我將解釋幾個關於 Ubuntu 的 root 用户的重要的東西。</p><p><strong>請記住，儘管我正在從 Ubuntu 用户的角度編寫這篇文章，它應該對大多數的 Linux 發行版也是有效的。</strong></p><p>你將在這篇文章中學到下面的內容：</p><ul><li>為什麼在 Ubuntu 中禁用 root 用户</li><li>像 root 用户一樣使用命</li><li>切換為 root 用户</li><li>解鎖 root 用户</li></ul><h3 id="什麼是-root-用户-為什麼它在-ubuntu-中被鎖定" tabindex="-1">什麼是 root 用户？為什麼它在 Ubuntu 中被鎖定？ <a class="header-anchor" href="#什麼是-root-用户-為什麼它在-ubuntu-中被鎖定" aria-label="Permalink to “什麼是 root 用户？為什麼它在 Ubuntu 中被鎖定？”">​</a></h3>',8)),e("p",null,[s[1]||(s[1]=t("在 Linux 中，有一個稱為 ",-1)),i(o,{href:"http://www.linfo.org/root.html"},{default:n(()=>[...s[0]||(s[0]=[t("root",-1)])]),_:1}),s[2]||(s[2]=t(" 的超級用户。這是超級管理員賬號，它可以做任何事以及使用系統的一切東西。它可以在你的 Linux 系統上訪問任何文件和運行任何命令。",-1))]),s[31]||(s[31]=e("p",null,"能力越大，責任越大。root 用户給予你完全控制系統的能力，因此，它應該被謹慎地使用。root 用户可以訪問系統文件，運行更改系統配置的命令。因此，一個錯誤的命令可能會破壞系統。",-1)),e("p",null,[s[4]||(s[4]=t("這就是為什麼 ",-1)),i(o,{href:"https://ubuntu.com/"},{default:n(()=>[...s[3]||(s[3]=[t("Ubuntu",-1)])]),_:1}),s[5]||(s[5]=t(" 和其它基於 Ubuntu 的發行版默認鎖定 root 用户，以從意外的災難中挽救你的原因。",-1))]),s[32]||(s[32]=a('<p>對於你的日常任務，像移動你家目錄中的文件，從互聯網下載文件，創建文檔等等，你不需要擁有 root 權限。</p><p><strong>打個比方來更好地理解它。假設你想要切一個水果，你可以使用一把廚房用刀。假設你想要砍一顆樹，你就得使用一把鋸子。現在，你可以使用鋸子來切水果，但是那不明智，不是嗎？</strong>_</p><p>這意味着，你不能是 Ubuntu 中 root 用户或者不能使用 root 權限來使用系統嗎？不，你仍然可以在 <code>sudo</code> 的幫助下來擁有 root 權限來訪問(在下一節中解釋)。</p><blockquote><p><strong>要點：</strong> 使用於常規任務，root 用户權限太過強大。這就是為什麼不建議一直使用 root 用户。你仍然可以使用 root 用户來運行特殊的命令。</p></blockquote><h3 id="如何在-ubuntu-中像-root-用户一樣運行命令" tabindex="-1">如何在 Ubuntu 中像 root 用户一樣運行命令？ <a class="header-anchor" href="#如何在-ubuntu-中像-root-用户一樣運行命令" aria-label="Permalink to “如何在 Ubuntu 中像 root 用户一樣運行命令？”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/01/sudo_sandwich.png?ssl=1" alt="Image Credit: xkcd"></p>',6)),e("p",null,[s[7]||(s[7]=t("對於一些系統的特殊任務來説，你將需要 root 權限。例如。如果你想",-1)),i(o,{href:"https://itsfoss.com/update-ubuntu/"},{default:n(()=>[...s[6]||(s[6]=[t("通過命令列更新 Ubuntu",-1)])]),_:1}),s[8]||(s[8]=t("，你不能作為一個常規用户運行該命令。它將給出權限被拒絕的錯誤。",-1))]),s[33]||(s[33]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt update</span></span>
<span class="line"><span>Reading package lists... Done</span></span>
<span class="line"><span>E: Could not open lock file /var/lib/apt/lists/lock - open (13: Permission denied)</span></span>
<span class="line"><span>E: Unable to lock directory /var/lib/apt/lists/</span></span>
<span class="line"><span>W: Problem unlinking the file /var/cache/apt/pkgcache.bin - RemoveCaches (13: Permission denied)</span></span>
<span class="line"><span>W: Problem unlinking the file /var/cache/apt/srcpkgcache.bin - RemoveCaches (13: Permission denied)</span></span></code></pre></div><p>那麼，你如何像 root 用户一樣運行命令？簡單的答案是，在命令前添加 <code>sudo</code>，來像 root 用户一樣運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>Ubuntu 和很多其它的 Linux 發行版使用一個被稱為 <code>sudo</code> 的特殊程序機制。<code>sudo</code> 是一個以 root 用户（或其它用户）來控制運行命令訪問的程序。</p><p>實際上，<code>sudo</code> 是一個非常多用途的工具。它可以配置為允許一個用户像 root 用户一樣來運行所有的命令，或者僅僅一些命令。你也可以配置為無需密碼即可使用 sudo 運行命令。這個主題內容比較豐富，也許我將在另一篇文章中詳細討論它。</p>`,5)),e("p",null,[s[10]||(s[10]=t("就目前而言，你應該知道",-1)),i(o,{href:"https://itsfoss.com/install-ubuntu/"},{default:n(()=>[...s[9]||(s[9]=[t("當你安裝 Ubuntu 時",-1)])]),_:1}),s[11]||(s[11]=t("，你必須創建一個用户賬號。這個用户賬號在你係統上以管理員身份來工作，並且按照 Ubuntu 中的默認 sudo 策略，它可以在你的系統上使用 root 用户權限來運行任何命令。",-1))]),s[34]||(s[34]=a(`<p><code>sudo</code> 的問題是，運行 <strong>sudo 不需要 root 用户密碼，而是需要用户自己的密碼</strong>。</p><p>並且這就是為什麼當你使用 <code>sudo</code> 運行一個命令，會要求輸入正在運行 <code>sudo</code> 命令的用户的密碼的原因：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[email protected]:~$ sudo apt update</span></span>
<span class="line"><span>[sudo] password for abhishek:</span></span></code></pre></div><p>正如你在上面示例中所見 <code>abhishek</code> 在嘗試使用 <code>sudo</code> 來運行 <code>apt update</code> 命令，系統要求輸入 <code>abhishek</code> 的密碼。</p><p><strong>如果你對 Linux 完全不熟悉，當你在終端中開始輸入密碼時，你可能會驚訝，在屏幕上什麼都沒有發生。這是十分正常的，因為作為默認的安全功能，在屏幕上什麼都不會顯示。甚至星號（<code>*</code>）都沒有。輸入你的密碼並按回車鍵。</strong></p><blockquote><p><strong>要點：</strong>為在 Ubuntu 中像 root 用户一樣運行命令，在命令前添加 <code>sudo</code>。 當被要求輸入密碼時，輸入你的賬户的密碼。當你在屏幕上輸入密碼時，什麼都看不到。請繼續輸入密碼，並按回車鍵。</p></blockquote><h3 id="如何在-ubuntu-中成為-root-用户" tabindex="-1">如何在 Ubuntu 中成為 root 用户？ <a class="header-anchor" href="#如何在-ubuntu-中成為-root-用户" aria-label="Permalink to “如何在 Ubuntu 中成為 root 用户？”">​</a></h3><p>你可以使用 <code>sudo</code> 來像 root 用户一樣運行命令。但是，在某些情況下，你必須以 root 用户身份來運行一些命令，而你總是忘了在命令前添加 <code>sudo</code>，那麼你可以臨時切換為 root 用户。</p><p><code>sudo</code> 命令允許你來模擬一個 root 用户登錄的 shell ，使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo -i</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[email protected]:~$ sudo -i</span></span>
<span class="line"><span>[sudo] password for abhishek:</span></span>
<span class="line"><span>[email protected]:~# whoami</span></span>
<span class="line"><span>root</span></span>
<span class="line"><span>[email protected]:~#</span></span></code></pre></div><p>你將注意到，當你切換為 root 用户時，shell 命令提示符從 <code>$</code>（美元符號）更改為 <code>#</code>（英鎊符號）。我開個（拙劣的）玩笑，英鎊比美元強大。</p><p><strong>雖然我已經向你顯示如何成為 root 用户，但是我必須警告你，你應該避免作為 root 用户使用系統。畢竟它有阻攔你使用 root 用户的原因。</strong></p><p>另外一種臨時切換為 root 用户的方法是使用 <code>su</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo su</span></span></code></pre></div><p>如果你嘗試使用不帶有的 <code>sudo</code> 的 <code>su</code> 命令，你將遇到 “su authentication failure” 錯誤。</p><p>你可以使用 <code>exit</code> 命令來恢復為正常用户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>exit</span></span></code></pre></div><h3 id="如何在-ubuntu-中啓用-root-用户" tabindex="-1">如何在 Ubuntu 中啓用 root 用户？ <a class="header-anchor" href="#如何在-ubuntu-中啓用-root-用户" aria-label="Permalink to “如何在 Ubuntu 中啓用 root 用户？”">​</a></h3><p>現在你知道，root 用户在基於 Ubuntu 發行版中是默認鎖定的。</p><p>Linux 給予你在系統上想做什麼就做什麼的自由。解鎖 root 用户就是這些自由之一。</p><p>如果出於某些原因，你決定啓用 root 用户，你可以通過為其設置一個密碼來做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd root</span></span></code></pre></div>`,23)),e("p",null,[s[13]||(s[13]=t("再強調一次，不建議使用 root 用户，並且我也不鼓勵你在桌面上這樣做。如果你忘記了密碼，你將不能再次",-1)),i(o,{href:"https://itsfoss.com/how-to-hack-ubuntu-password/"},{default:n(()=>[...s[12]||(s[12]=[t("在 Ubuntu 中更改 root 用户密碼",-1)])]),_:1}),s[14]||(s[14]=t("。（LCTT 譯註：可以通過單用户模式修改。）",-1))]),s[35]||(s[35]=a('<p>你可以通過移除密碼來再次鎖定 root 用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo passwd -dl root</span></span></code></pre></div><h3 id="最後" tabindex="-1">最後… <a class="header-anchor" href="#最後" aria-label="Permalink to “最後…”">​</a></h3><p>我希望你現在對 root 概念理解得更好一點。如果你仍然有些關於它的困惑和問題，請在評論中讓我知道。我將嘗試回答你的問題，並且也可能更新這篇文章。</p><hr>',5)),e("p",null,[s[16]||(s[16]=t("via: ",-1)),i(o,{href:"https://itsfoss.com/root-user-ubuntu/"},{default:n(()=>[...s[15]||(s[15]=[t("https://itsfoss.com/root-user-ubuntu/",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=t("作者：",-1)),i(o,{href:"https://itsfoss.com/author/abhishek/"},{default:n(()=>[...s[17]||(s[17]=[t("Abhishek Prakash",-1)])]),_:1}),s[22]||(s[22]=t(" 選題：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[18]||(s[18]=[t("lujun9972",-1)])]),_:1}),s[23]||(s[23]=t(" 譯者：",-1)),i(o,{href:"https://github.com/robsean"},{default:n(()=>[...s[19]||(s[19]=[t("robsean",-1)])]),_:1}),s[24]||(s[24]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...s[20]||(s[20]=[t("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[25]||(s[25]=[t("LCTT",-1)])]),_:1}),s[28]||(s[28]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...s[26]||(s[26]=[t("Linux中國",-1)])]),_:1}),s[29]||(s[29]=t(" 榮譽推出",-1))])])}const x=l(d,[["render",b]]);export{C as __pageData,x as default};
